opciones_seleccionables.className:
{[
              styles.pill,
              layout === 'stacked' ? styles.pillStacked : '',
              isActive ? styles.pillActive : '',
              isDisabled ? styles.pillDisabled : '',
            ].filter(Boolean).join(' ')}

campos_entrada.className:
{[
            styles.input,
            isFocused ? styles.inputFocused : '',
            error ? styles.inputError : '',
            disabled ? styles.inputDisabled : '',
          ].filter(Boolean).join(' ')}

botones_accion.className:
{[
            styles.trigger,
            error ? styles.triggerError : '',
            disabled ? styles.triggerDisabled : '',
            !displayValue ? styles.triggerPlaceholder : '',
          ].filter(Boolean).join(' ')}

{`px-4 py-2 text-xs font-semibold rounded-xl border transition ${
                forceReducedMotion
                  ? 'bg-amber-500/20 border-amber-500 text-amber-300'
                  : 'bg-silver-800/40 border-silver-600/30 text-silver-300 hover:bg-silver-800/70'
              }`}

{`px-3 py-1.5 text-xs font-medium rounded-lg transition ${
                selectedCategory === cat
                  ? 'bg-white text-black font-semibold shadow'
                  : 'bg-silver-900/60 text-silver-400 hover:bg-silver-850 hover:text-white border border-silver-800'
              }`}

{`px-2 py-0.5 rounded text-[11px] ${
                  iconSize === s ? 'bg-primary text-white font-bold' : 'hover:text-white'
                }`}

{`px-2 py-0.5 rounded text-[11px] ${
                  iconStroke === w ? 'bg-primary text-white font-bold' : 'hover:text-white'
                }`}

tarjetas_paneles.className:
{`${styles.card} ${!n.leida ? styles.cardUnread : ''} ${
                            styles[`nivel${n.nivel}`]
                          } ${n.deep_link || !n.leida ? styles.cardClickable : ''} ${
                            activeMenuId === n.id || activeSilenceId === n.id ? styles.cardActiveMenu : ''
                          }`}

{`
            ${styles.cardInner}
            ${isFlipping && flipDirection === 'toBack' ? styles.animatingToBack : ''}
            ${isFlipping && flipDirection === 'toFront' ? styles.animatingToFront : ''}
            ${!isFlipping && isFlipped ? styles.isFlippedFlat : ''}
            ${!isFlipping && !isFlipped ? styles.isFrontFlat : ''}
          `}

modales_dialogos.className:
{`${styles.dot} ${
              (metodoPago === 'credito'
                ? step === 3
                : esDebitoUsdEnPesos
                ? step === 4
                : step === 3)
                ? styles.dotActive
                : styles.dotInactive
            }`}

{`${styles.slide} ${
              step === 3
                ? styles.slideVisible
                : step < 3
                ? (slideDirection === 'forward' ? styles.slideEnterRight : styles.slideEnterLeft)
                : (slideDirection === 'forward' ? styles.slideExitLeft : styles.slideExitRight)
            }`}

elementos_informativos.className:
{`${styles.tagBadge} ${
                            tag === 'NUEVA' ? styles.tagNueva :
                            tag === 'CUOTA' ? styles.tagCuota :
                            tag === 'CARGO BANCARIO' ? styles.tagCargo :
                            styles.tagDuplicado
                          }`}

{`${styles.tagBadge} ${
                        tag === 'NUEVA' ? styles.tagNueva :
                        tag === 'CUOTA' ? styles.tagCuota :
                        tag === 'CARGO BANCARIO' ? styles.tagCargo :
                        styles.tagDuplicado
                      }`}

variants.className:
{[
              styles.pill,
              layout === 'stacked' ? styles.pillStacked : '',
              isActive ? styles.pillActive : '',
              isDisabled ? styles.pillDisabled : '',
            ].filter(Boolean).join(' ')}
